//! The write hooks of Bucket: they run, in the write's own transaction, the hook triggers the schema
//! declares for it and stage the events it declares with `on:`.
//!
//! Generated by metaphor-schema. Do not edit manually.
//!
//! They run around the repository write: `before` the triggers keyed `before_*`, after the row is written
//! and its lifecycle hooks have run, the `after_*` triggers in file order and then the declared events,
//! all before the commit. A failure of any of them rolls the write back, so a committed write always has
//! its events and the effects of its triggers. Delivery to subscribers is the outbox relay's, at least once.
#[allow(unused_imports)]
use backbone_core::write_hooks::{payload_from_row, Change, DeclaredEvent, NotificationRequested, WriteCtx, WriteHooks};
#[allow(unused_imports)]
use backbone_core::{PersistentEntity, ServiceError, ServiceResult};

use crate::domain::entity::Bucket;
#[allow(unused_imports)]
use crate::domain::event::declared;
use crate::application::triggers::BucketTriggers;

/// What a condition that reads the writer or the time of the write evaluates against.
#[allow(dead_code)]
struct EvalCtx {
    actor: Option<String>,
    at: chrono::DateTime<chrono::Utc>,
}

/// Runs the triggers of Bucket and stages its declared events. `triggers` is the hand-written half (`BucketTriggersImpl`).
pub struct BucketWriteHooks {
    triggers: std::sync::Arc<dyn BucketTriggers>,
}

impl BucketWriteHooks {
    /// The hooks over the hand-written half of the triggers.
    pub fn new(triggers: std::sync::Arc<dyn BucketTriggers>) -> Self {
        Self { triggers }
    }
}

#[async_trait::async_trait]
impl WriteHooks<Bucket> for BucketWriteHooks {
    fn outbox_schema(&self) -> Option<&str> {
        Some("bucket")
    }

    #[allow(unused_variables, unused_assignments)]
    async fn before(&self, write: &WriteCtx, change: &mut Change<'_, Bucket>) -> ServiceResult<()> {
        use backbone_core::row_rule as r;
        backbone_core::write_hooks::in_trigger(async {
            let old_json = change.before().and_then(|b| serde_json::to_value(b).ok());
            let old_row = old_json.as_ref().unwrap_or(&serde_json::Value::Null);
            let ctx = EvalCtx { actor: write.actor.clone(), at: chrono::Utc::now() };
            let aggregate_id = change.subject().entity_id();
            let company = write.company_of(&serde_json::to_value(change.subject()).unwrap_or(serde_json::Value::Null));
            let _ = (&ctx, &old_row, &aggregate_id, company);
            {
                let row = &serde_json::to_value(change.subject()).unwrap_or(serde_json::Value::Null);
                // `before_create`: before_create (bucket.hook.yaml:186)
                if matches!(change, Change::Created { .. }) {
                    if let Some(entity) = change.after_mut() {
                        self.triggers.before_create__derive_slug(write, entity).await?;
                    }
                    let row = &serde_json::to_value(change.subject()).unwrap_or(serde_json::Value::Null);
                    if r::holds(&r::or(r::is_null(r::field(row, "root_path")), r::eq(r::field(row, "root_path"), r::text("")))) {
                        if let Some(entity) = change.after_mut() {
                            entity.root_path = serde_json::from_value(r::to_json(&r::add(r::add(r::field(row, "owner_id"), r::text("/")), r::field(row, "slug"))))
                                .map_err(|e| ServiceError::Validation(format!("trigger `Bucket.before_create` could not set `root_path`: {e}")))?;
                        }
                        let row = &serde_json::to_value(change.subject()).unwrap_or(serde_json::Value::Null);
                    }
                }
            }
            {
                let row = &serde_json::to_value(change.subject()).unwrap_or(serde_json::Value::Null);
                // `before_delete`: before_delete (bucket.hook.yaml:203)
                if matches!(change, Change::Deleted { hard: false, .. }) && r::holds(&r::eq(r::field(row, "file_count"), r::Val::Num(0.0_f64))) {
                    tracing::info!(target: "backbone::trigger", trigger = "Bucket.before_delete", correlation_id = %write.correlation_id, log_event = "bucket.deleting", bucket_id = %r::to_json(&r::field(row, "id")));
                }
            }
            Ok(())
        })
        .await
    }

    #[allow(unused_variables, unused_assignments)]
    async fn after(&self, write: &WriteCtx, change: &Change<'_, Bucket>) -> ServiceResult<()> {
        use backbone_core::row_rule as r;
        let subject = change.subject();
        let row = serde_json::to_value(subject)
            .map_err(|e| ServiceError::Internal(format!("a row could not be read for its events: {e}")))?;
        let row = &row;
        let old = change.before().and_then(|b| serde_json::to_value(b).ok());
        let old_row = old.as_ref().unwrap_or(&serde_json::Value::Null);
        let ctx = EvalCtx { actor: write.actor.clone(), at: chrono::Utc::now() };
        let aggregate_id = subject.entity_id();
        let company = write.company_of(row);
        let _ = (&aggregate_id, company);
        let _ = &ctx;

        backbone_core::write_hooks::in_trigger(async {
            // `after_create`: after_create (bucket.hook.yaml:193)
            if matches!(change, Change::Created { .. }) {
                self.triggers.after_create__call_storage_provisioning_service_create_bucket_directory(write, subject).await?;
                {
                    let mut payload = serde_json::Map::new();
                    payload.insert("bucket_id".to_string(), r::to_json(&r::field(row, "id")));
                    payload.insert("owner_id".to_string(), r::to_json(&r::field(row, "owner_id")));
                    payload.insert("name".to_string(), r::to_json(&r::field(row, "name")));
                    payload.insert("bucket_type".to_string(), r::to_json(&r::field(row, "bucket_type")));
                    let event: declared::BucketCreatedEvent = serde_json::from_value(serde_json::Value::Object(payload))
                        .map_err(|e| ServiceError::Internal(format!("trigger `Bucket.after_create` could not build BucketCreatedEvent: {e}")))?;
                    write.stage(event.record_for(&aggregate_id, company, write)).await?;
                }
                tracing::info!(target: "backbone::trigger", trigger = "Bucket.after_create", correlation_id = %write.correlation_id, log_event = "bucket.created", bucket_id = %r::to_json(&r::field(row, "id")), owner_id = %r::to_json(&r::field(row, "owner_id")), name = %r::to_json(&r::field(row, "name")));
            }
            // `after_update_status`: after_update status (bucket.hook.yaml:199)
            if matches!(change, Change::Updated { .. } | Change::Transitioned { .. }) && change.field_changed("status") {
                tracing::info!(target: "backbone::trigger", trigger = "Bucket.after_update_status", correlation_id = %write.correlation_id, log_event = "bucket.status_changed", bucket_id = %r::to_json(&r::field(row, "id")), old_status = %r::to_json(&r::field(old_row, "status")), new_status = %r::to_json(&r::field(row, "status")));
            }
            // `after_delete`: after_delete (bucket.hook.yaml:208)
            if matches!(change, Change::Deleted { hard: false, .. }) {
                self.triggers.after_delete__queue_cleanup_bucket_storage(write, subject).await?;
                tracing::info!(target: "backbone::trigger", trigger = "Bucket.after_delete", correlation_id = %write.correlation_id, log_event = "bucket.deleted", bucket_id = %r::to_json(&r::field(row, "id")), owner_id = %r::to_json(&r::field(row, "owner_id")));
            }
            // `on_enter active`: on_enter active (bucket.hook.yaml:15)
            if matches!(change, Change::Transitioned { to: Some(to), .. } if to == "active") {
                tracing::info!(target: "backbone::trigger", trigger = "Bucket.on_enter active", correlation_id = %write.correlation_id, log_event = "bucket.activated", bucket_id = %r::to_json(&r::field(row, "id")));
            }
            // `on_enter readonly`: on_enter readonly (bucket.hook.yaml:20)
            if matches!(change, Change::Transitioned { to: Some(to), .. } if to == "readonly") {
                tracing::info!(target: "backbone::trigger", trigger = "Bucket.on_enter readonly", correlation_id = %write.correlation_id, log_event = "bucket.locked", bucket_id = %r::to_json(&r::field(row, "id")));
            }
            // `on_enter archived`: on_enter archived (bucket.hook.yaml:24)
            if matches!(change, Change::Transitioned { to: Some(to), .. } if to == "archived") {
                tracing::info!(target: "backbone::trigger", trigger = "Bucket.on_enter archived", correlation_id = %write.correlation_id, log_event = "bucket.archived", bucket_id = %r::to_json(&r::field(row, "id")));
                self.triggers.on_enter_archived__queue_compress_archived_bucket(write, change.before().unwrap_or(subject), subject).await?;
            }
            // `on_enter deleted`: on_enter deleted (bucket.hook.yaml:29)
            if matches!(change, Change::Transitioned { to: Some(to), .. } if to == "deleted") {
                self.triggers.on_enter_deleted__set_metadata_deleted_at(write, change.before().unwrap_or(subject), subject).await?;
                self.triggers.on_enter_deleted__queue_schedule_bucket_purge(write, change.before().unwrap_or(subject), subject).await?;
                {
                    let mut payload = serde_json::Map::new();
                    payload.insert("bucket_id".to_string(), r::to_json(&r::field(row, "id")));
                    payload.insert("owner_id".to_string(), r::to_json(&r::field(row, "owner_id")));
                    let event: declared::BucketDeletedEvent = serde_json::from_value(serde_json::Value::Object(payload))
                        .map_err(|e| ServiceError::Internal(format!("trigger `Bucket.on_enter deleted` could not build BucketDeletedEvent: {e}")))?;
                    write.stage(event.record_for(&aggregate_id, company, write)).await?;
                }
            }
            Ok(())
        })
        .await?;

        Ok(())
    }
}
